import java.util.Scanner;

public class Main
{
	private static void swap(int gcdNum[],int get_time,int b)
	{
		int datasetint=gcdNum[get_time];
		gcdNum[get_time]=gcdNum[b];
		gcdNum[b]=datasetint;
	}
	public static void main(String[] args)
	{
		Scanner scan=new Scanner(System.in);
		int nextInt2DArray=scan.nextInt();
		int longSortedArr=scan.nextInt();
		int get_time,b;
		int[] gcdNum=new int[nextInt2DArray];
		for(int columnW=0;columnW<gcdNum.length;columnW++){
			gcdNum[columnW]=columnW+1;
		}
		for(int columnW=0;columnW<longSortedArr;columnW++){
			String[] datasetint=scan.next().split(",");
			get_time=Integer.parseInt(datasetint[0]);
			b=Integer.parseInt(datasetint[1]);
			swap(gcdNum,get_time-1,b-1);
		}
		for(int columnW=0;columnW<gcdNum.length;columnW++){
			System.out.println(gcdNum[columnW]);
		}
		scan.close();
	}
}

