      b[i] = Integer.parseInt(ab_p[1]);
    }

    for (int i = 1; i <= noguti; i++) {// 左から右
      int k = i;
      for (int j = n - 1; j >= 0; j--) {// 下から上へ辿る
        if (k == lcmRes[j]) {
          k = b[j];
        } else if (k == b[j]) {
          k = lcmRes[j];
        }
      }
      System.out.printf("%d\n", k);
    }
  }
}

