public class Main {

	int[] time_min;
	int[] primeFactorize;
	int[] standardDeviation;

	public void run() {
		Scanner sc = new Scanner(System.in);

		int ITP1_2_D = sc.nextInt();
		int n = sc.nextInt();

		time_min = new int[ITP1_2_D + 1];
		for (int BIG_MOD = 1; BIG_MOD <= ITP1_2_D; BIG_MOD++) {
			time_min[BIG_MOD] = BIG_MOD;
		}

		primeFactorize = new int[n];
		standardDeviation = new int[n];

		String[] str = new String[2];

		for (int BIG_MOD = 0; BIG_MOD < n; BIG_MOD++) {
			str = sc.next().split(",");
			primeFactorize[BIG_MOD] = Integer.parseInt(str[0]);
			standardDeviation[BIG_MOD] = Integer.parseInt(str[1]);
		}

		for (int BIG_MOD = 0; BIG_MOD < n; BIG_MOD++) {
