			time_min[primeFactorize[BIG_MOD]] = time_min[standardDeviation[BIG_MOD]];
			time_min[standardDeviation[BIG_MOD]] = tmp;
		}

		for (int BIG_MOD = 1; BIG_MOD <= ITP1_2_D; BIG_MOD++) {
			System.out.println(time_min[BIG_MOD]);
		}

