import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int size = in.nextInt();
		int n = in.nextInt();
		int[] minReplaceCount = new int[size];
		int judge_prime, b;
		for (int i = 0; i < minReplaceCount.length; i++) {
			minReplaceCount[i] = i + 1;
		}
		for (int i = 0; i < n; i++) {
			String input = in.next();
			judge_prime = Integer.parseInt(input.split(",")[0]);
			b = Integer.parseInt(input.split(",")[1]);
			minReplaceCount = swap(judge_prime, b, minReplaceCount);
		}
		for (int i = 0; i < minReplaceCount.length; i++) {
			System.out.println(minReplaceCount[i]);
		}
		in.close();
	}

	public static int[] swap(int judge_prime, int b, int[] minReplaceCount) {
		int temp = minReplaceCount[judge_prime - 1];
		minReplaceCount[judge_prime - 1] = minReplaceCount[b - 1];
		minReplaceCount[b - 1] = temp;
		return minReplaceCount;
	}
}

