class Main {
	public static void main(String[] args) {
		Scanner stdIn = new Scanner(System.in);

		int row = stdIn.nextInt();
		int[] mincnt = new int[row];

		for (int i = 0; i < row; i++) {
			mincnt[i] = stdIn.nextInt();
		}

		insertionSort(mincnt, row);

	}

	static void insertionSort(int[] mincnt, int row) {
		int minN;
		int tmp;

		for (int i = 1; i < row; i++) {
			for (int k = 0; k < row - 1; k++) {
				System.out.print(mincnt[k] + " ");
			}
			System.out.println(mincnt[row - 1]);
			tmp = mincnt[i];
			minN = i - 1;
			while (minN >= 0 && mincnt[minN] > tmp) {
				mincnt[minN + 1] = mincnt[minN];
				minN--;
			}
			mincnt[minN + 1] = tmp;
		}
		for (int k = 0; k < row - 1; k++) {
			System.out.print(mincnt[k] + " ");
		}
		System.out.println(mincnt[row - 1]);
	}
}

