public class Main {

	public static void main(String[] args) {

		int n;
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		int[] minLen = new int[n];
		for (int Dig = 0; Dig < n; Dig++) {
			minLen[Dig] = sc.nextInt();
		}

		print(minLen);
		insertionSort2(minLen);

	}

	static void print(int[] minLen) {
		for (int Dig = 0; Dig < minLen.length; Dig++) {
			System.out.print(minLen[Dig]);
			if (Dig != minLen.length-1) {
				System.out.print(" ");
			} else {
				System.out.print("\n");
			}
		}
	}

	static void insertionSort1(int[] minLen) {
		for (int Dig = 1; Dig < minLen.length; Dig++) {
			for (int j = 0; j < Dig; j++) {
				if (minLen[Dig] < minLen[j]) {
					int tmp = minLen[Dig];
					for (int k = Dig - 1; k >= j; k--) {
						minLen[k+1] = minLen[k];
					}
					minLen[j] = tmp;
				}
			}
			print(minLen);
		}
	}
	static void insertionSort2(int[] minLen) {
		for (int Dig = 1; Dig < minLen.length; Dig++) {
			int v = minLen[Dig];
			int j = Dig-1;
			while (j >= 0 && minLen[j] > v) {
				minLen[j+1] = minLen[j];
				j--;
			}
			minLen[j+1] = v;
			print(minLen);
		}
	}

}

