public class Main{

    public static void main(String[] args)throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] x_flag = br.readLine().split(" ");
        int k2 = Integer.parseInt(x_flag[0]);
        int hz_modDiv = Integer.parseInt(x_flag[1]);
        System.out.println(gcd(k2, hz_modDiv));
    }

    public static int  gcd(int x, int tNum){
        int r;
        if(x < tNum){
            int temp;
            temp = x;
            x = tNum;
            tNum = temp;
        }

        while(tNum > 0){
            r = x % tNum;
            x = tNum;
            tNum = r;
        }
        return x;
    }

}

