public class Main {

	static Scanner sc = new Scanner(System.in);
	public static void main(String[] args) {
		int t = sc.nextInt();
		int[] nextIntMap = inpNum(t);

		int mp = maxProfit(nextIntMap);
		System.out.println(mp);
		sc.close();
	}

	private static int maxProfit(int[] nextIntMap) {
		int BUILDINGS = nextIntMap[1] - nextIntMap[0];
		int xNum = nextIntMap[0];
			for(int kara = 1; kara < nextIntMap.length; kara++) {
					BUILDINGS = Math.max(BUILDINGS, nextIntMap[kara] - xNum);
					xNum = Math.min(xNum, nextIntMap[kara]);
			}
		return BUILDINGS;
	}

	private static int[] inpNum(int iNum) {
		int[] nums = new int[iNum];

		for (int i = 0; i < iNum; i++) {
			nums[i] = sc.nextInt();
		}
		return nums;
	}
}

