    //並べ替え
    private static void bubbleSort(int minValue[],int N){
	int flag = 1;
	int count = 0;

	while(flag != 0){
	    flag = 0;
	    for(int j=N-1; j > 0; j--){
		if(minValue[j] < minValue[j-1]){
		    int v = minValue[j];
		    int w = minValue[j-1];
		    minValue[j] = w;
		    minValue[j-1] = v;
		    flag = 1;
		    count++;
		}	
	    }
	}
	Print(minValue,N);
	System.out.println(count);
    }
