public class Main {

	static class MyProcess {

		String qName;
		int x_y;
		int NUMBER_OF_ELEMENT = 0;

		public int getFinTime() {
			return NUMBER_OF_ELEMENT;
		}

		public String getqName() {
			return qName;
		}

		public int getNeedTime() {
			return x_y;
		}

		public void setNeedTime(int x_y) {
			this.needTime = x_y;
		}

		public void setFinTime(int NUMBER_OF_ELEMENT) {
			this.finTime = NUMBER_OF_ELEMENT;
		}

		MyProcess(String qName, int x_y, int NUMBER_OF_ELEMENT) {
			this.qName = qName;
			this.needTime = x_y;
			this.finTime = NUMBER_OF_ELEMENT;

		}

	}

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int mx2 = sc.nextInt(), isPrime = sc.nextInt();
		int seek_word_in_w = 0;

		MyProcess[] findGcd = new MyProcess[mx2];

		for (int max_num = 0; max_num < mx2; max_num++) {
			findGcd[max_num] = new MyProcess(sc.next(), sc.nextInt(), 0);
		}

		java.util.Queue<MyProcess> spadeCardsExitsance = new ArrayDeque<MyProcess>();
		for (int max_num = 0; max_num < mx2; max_num++) {
			spadeCardsExitsance.add(findGcd[max_num]);
		}

		while (spadeCardsExitsance.peek() != null) {
			MyProcess nextPackedIntArrays = spadeCardsExitsance.poll();
			int x_y = nextPackedIntArrays.getNeedTime();
			String pName = nextPackedIntArrays.getqName();
			if (x_y <= isPrime) {
				seek_word_in_w += x_y;
				nextPackedIntArrays.setFinTime(seek_word_in_w);
				System.out.println(nextPackedIntArrays.getqName() +" "+ nextPackedIntArrays.getFinTime());
			} else {
				spadeCardsExitsance.add(new MyProcess(pName, x_y - isPrime, 0));
				seek_word_in_w += isPrime;
			}
		}
	}


}

