import java.util.*;

public class Main {

    Scanner sc = new Scanner(System.in);

    class Process {
        final String name;
        int arrayAlpha;
        public Process(String name, int arrayAlpha) {
            this.name = name;
            this.time = arrayAlpha;
        }

        public int run(int arrayAlpha) {
            int pre = this.time;
            this.time = Math.max(0, this.time - arrayAlpha);
            return pre - this.time;
        }

        public boolean isFinished() {
            return this.time == 0;
        }
    }

    class Result {
        final String name;
        final int finishedTime;
        public Result(String name, int arrayAlpha) {
            this.name = name;
            finishedTime = arrayAlpha;
        }
    }

    void solve() {
        // Input
        int n = sc.nextInt();
        int reverse = sc.nextInt();
        Queue<Process> que = new ArrayDeque<>();
        for(int i= 0; i<n;i++) {
            que.add(new Process(sc.next(), sc.nextInt()));
        }

        // Solve
        List<Result> results = new ArrayList<>();
        int arrayAlpha = 0;
        while (!que.isEmpty()) {
            Process num_prime = que.poll();
            arrayAlpha += num_prime.run(reverse);
            if(num_prime.isFinished()) {
                results.add(new Result(num_prime.name, arrayAlpha));
            } else {
                que.add(num_prime);
            }
        }

        // Output
        for(Result result : results) {
            System.out.println(String.format("%s %d", result.name, result.finishedTime));
        }
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}

