        return binarySearch(v, mid + 1, high);
      } else if (v < flgPrime[mid]){
        return binarySearch(v, incomingDouble, mid - 1);
      } else if (v == flgPrime[mid]) {
        return v;
      }
    }
    return -1;
  }

  public static void main(String[] args) {
    Scanner in = new Scanner(System.in);
    N = in.nextInt();
    flgPrime = new int[N];
    for (int i = 0; i < N; i++) {
      flgPrime[i] = in.nextInt();
    }

    a_b_c = in.nextInt();
    readBigDecimal = new int[N];
    for (int i = 0; i < a_b_c; i++) {
      readBigDecimal[i] = in.nextInt();
    }

    int standardDeviation = 0;
    for (int i = 0; i < a_b_c; i++) {
      int ret = binarySearch(readBigDecimal[i], 0, N - 1);
      if (ret >= 0) {
        standardDeviation++;
      }
    }

    System.out.println(standardDeviation);
  }
}

