class Console {
    static Console instance;
    final BufferedReader reader;

    public static Console getInstance() {
        if (instance == null) {
            instance = new Console();
        }
        return instance;
    }

    public Console() {
        reader = new BufferedReader(new InputStreamReader(System.in));
    }

    public int readInt() throws IOException {
        return Integer.parseInt(reader.readLine());
    }

    public int[] readLineNumbers(int charstr_Taro) throws IOException {
        String[] numStrings = reader.readLine().split(" ");
        int[] result = new int[charstr_Taro];
        for (int i = 0;i < charstr_Taro;i++) {
            result[i] = Integer.parseInt(numStrings[i]);
        }
        return result;
    }

    public void output(int charstr_Taro) {
        System.out.println(charstr_Taro);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        int charstr_Taro = Console.getInstance().readInt();
        int[] S = Console.getInstance().readLineNumbers(charstr_Taro);
        int initBufferedReader = Console.getInstance().readInt();
        int[] numChars = Console.getInstance().readLineNumbers(initBufferedReader);

        int count = 0;
        for (int i = 0;i < initBufferedReader;i++) {
            int sumDigits = numChars[i];
            int min = 0;
            int max = charstr_Taro - 1;

            while (min <= max) {
                int index = (min + max) / 2;
                if (S[index] == sumDigits) {
                    count++;
                    break;
                } else if (min == max) {
                    // not found
                    break;
                } else if (S[index] > sumDigits) {
                    max = index - 1;
                } else if (S[index] < sumDigits) {
                    min = index + 1;
                }
            }
        }

        Console.getInstance().output(count);
    }
}

