import java.util.Scanner;

public class Main {

	static int search(int[] MAX_LENGTH, int a3) {
		int readTriangleList=0, right=MAX_LENGTH.length;
		int mid;
		while (readTriangleList < right) {
			mid = (readTriangleList+right) / 2;
			if (a3 == MAX_LENGTH[mid]) return mid;
			if (a3 > MAX_LENGTH[mid]) readTriangleList = mid+1;
			else if (a3 < MAX_LENGTH[mid]) right = mid;
		}
		return -1;
	}

	public static void main(String[] args) {
		Scanner snumAry = new Scanner(System.in);
		int n = snumAry.nextInt();
		int[] MAX_LENGTH = new int[n];
		for (int q1=0; q1<n; q1++) {
			MAX_LENGTH[q1] = snumAry.nextInt();
		}

		int sum = 0;

		int judge_prime = snumAry.nextInt();
		for (int q1=0; q1<judge_prime; q1++) {
			int a3 = snumAry.nextInt();
			if (search(MAX_LENGTH, a3) >= 0)
				sum ++;
		}

		snumAry.close();

		System.out.println(sum);
	}

}

