import java.util.Scanner;

public class Main{
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int greatestCommonDivisor = sc.nextInt();
		int prime_10 = sc.nextInt();
		int gcdLCM, Tl;
		int[] charNumber = new int[greatestCommonDivisor];
		int[] product = new int[prime_10];
		int[][] A = new int[greatestCommonDivisor][prime_10];
		int[] ns = new int[prime_10];
		int[] c = new int[greatestCommonDivisor];
		for (gcdLCM = 0; gcdLCM < A.length; gcdLCM++) {
			for (Tl = 0; Tl < A[gcdLCM].length; Tl++) {
				A[gcdLCM][Tl] = sc.nextInt();
			}
		}
		for (Tl = 0; Tl < ns.length; Tl++) {
			ns[Tl] = sc.nextInt();
		}
		for (gcdLCM = 0; gcdLCM < A.length; gcdLCM++) {
			for (Tl = 0; Tl < A[gcdLCM].length; Tl++) {
				product[Tl] = A[gcdLCM][Tl] * ns[Tl];
				charNumber[gcdLCM] += product[Tl];
			}
