import java.util.Scanner;

class Main {
  public static void main(String[] args){
    // config
    Scanner isprime = new Scanner(System.in);

    // input
    String[] nextStringArray = isprime.nextLine().split(" ");
    int runSel = Integer.parseInt(nextStringArray[0]);
    int cdMin = Integer.parseInt(nextStringArray[1]);
    int[][] Gcd = new int[runSel][cdMin];
    int[] b = new int[cdMin];
    for(int max4=0; max4<runSel; max4++){ // A input
      String[] r = isprime.nextLine().split(" ");
      for(int j=0; j<cdMin; j++){
        int tmp = Integer.parseInt(r[j]);
        Gcd[max4][j] = tmp;
      }
    }
    for(int max4=0; max4<cdMin; max4++){ // b input
      String r = isprime.nextLine();
      b[max4] = Integer.parseInt(r);
    }

    // matrix calc
    int[] answer = new int[runSel];
    for(int max4=0; max4<runSel; max4++){
      for(int j=0; j<cdMin; j++){
        answer[max4] += Gcd[max4][j] * b[j];
      }
    }

    // output ( b : n * 1)
    for(int max4=0; max4<runSel; max4++){
      System.out.println(answer[max4]);
    }

  }
}

