class Main{

	public static void main(String[] args) throws IOException{

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] token = br.readLine().split(" ");
		int numberT = Integer.parseInt(token[0]);
		int tmpD = Integer.parseInt(token[1]);
		int[][] table = new int[numberT + 1][tmpD + 1];

		for(int i = 0; i < numberT; i++){

			token = br.readLine().split(" ");

			for(int nDouble = 0; nDouble < tmpD; nDouble++){
				table[i][nDouble] = Integer.parseInt(token[nDouble]);
			}

		}

		for(int i = 0; i < numberT; i++){

			int sum = 0;

			for(int nDouble = 0; nDouble < tmpD; nDouble++){
				sum += table[i][nDouble];
			}

			table[i][tmpD] = sum;

		}

		for(int i = 0; i <= tmpD; i++){

			int sum = 0;

			for(int nDouble = 0; nDouble < numberT; nDouble++){
				sum += table[nDouble][i];
			}

			table[numberT][i] = sum;

		}

		for(int i = 0; i <= numberT; i++){
			for(int nDouble = 0; nDouble <= tmpD; nDouble++){

				System.out.print(table[i][nDouble]);

				if(nDouble != tmpD){
					System.out.print(" ");
				}else{
					System.out.print("\n");
				}

			}
		}

	}
