import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	final static String max_line = "-";

	public static void main(String[] args) {
		Scanner argc = new Scanner(System.in);

		ArrayList<String> resultList = new ArrayList<String>();

		String readIntArray;
		while (EndDecision(readIntArray = argc.nextLine())) {

			int K = Integer.parseInt(argc.nextLine());

			for (int topThree = 0; topThree < K; topThree++) {
				readIntArray = Shuffle(readIntArray, Integer.parseInt(argc.nextLine()));
			}
			resultList.add(readIntArray);
		}

		for (String mountainHeight : resultList) {
			System.out.println(mountainHeight);
		}

	}

	static String Shuffle(String readIntArray, int num) {
		String result = readIntArray.substring(num);
		result += readIntArray.substring(0, num);
		return result;
	}

	// 終了判定
	public static boolean EndDecision(String array) {
		if (array.equals(max_line)) {
			return false;
		} else {
			return true;
		}

	}

}

