	{
		BufferedReader var0 = new BufferedReader (new InputStreamReader (System.in));

		int sig = Integer.parseInt(var0.readLine());

		int beforeSubtructionRi = 0;

		int Range = 0;

		//勝負をkaisuu回行う
		for(int kai = 0; kai < sig; kai++)
		{
			String[] greaterValue = var0.readLine().split(" ");;

			for(int unmatch_min = 0; unmatch_min <= greaterValue[0].length(); unmatch_min++)
			{

				char md = 'a';

				int tarou = 0;

				int hanako = 0;

				int alphabet = 26;

				//太郎のカードの強さを調べる
				for(int num = 0; num < alphabet; num++,md++)
				{
					if(unmatch_min == greaterValue[0].length())
					{
						tarou = -1;

						break;
					}

					if(greaterValue[0].charAt(unmatch_min) == md)
					{
						tarou = num;

						break;
					}
				}

				md = 'a';

				//花子のカードの強さを調べる
				for(int num = 0; num < alphabet; num++,md++)
				{
					if(unmatch_min == greaterValue[1].length())
					{
						hanako = -1;

						break;
					}

					if(greaterValue[1].charAt(unmatch_min) == md)
					{
						hanako = num;

						break;
					}
				}

				//得点を振り分ける
				if(tarou > hanako)
				{
					beforeSubtructionRi = beforeSubtructionRi + 3;

					break;
				}

				else if(tarou < hanako)
				{
					Range = Range + 3;

					break;
				}

				else if(tarou == -1 && hanako == -1)
				{
					beforeSubtructionRi++;

					Range++;
				}
			}
		}

		System.out.println(beforeSubtructionRi + " " + Range);
	}
