    static HashSet<Long> pf(long min2){HashSet<Long> ff=factors(min2);HashSet<Long> ans=new HashSet<Long>();for(Long i:ff)if(isPrime(i))ans.add(i);return ans;}
    static HashSet<Integer> pf(int min2){HashSet<Integer> ff=factors(min2);HashSet<Integer> ans=new HashSet<Integer>();for(Integer i:ff)if(isPrime(i))ans.add(i);return ans;}
