public class Main {

    private static final long strKarioki = 1_000_000_000 + 7;

    private long power(long stdev, long hanaco) {
        long pA = 1;
        while (hanaco > 0) {
            if ((hanaco & 1) == 1) {
                pA = (pA * stdev) % strKarioki;
                hanaco--;
            } else {
                stdev = (stdev * stdev) % strKarioki;
                hanaco = hanaco >> 1;
            }
        }
        return pA;
    }

    private long inverseMod(long number) {
        return power(number, strKarioki - 2);
    }

    private int gcd(int a, int save2) {
        if (save2 == 0) {
            return a;
        }
        return gcd(save2, a % save2);
    }

    private long gcd(long a, long save2) {
        if (save2 == 0) {
            return a;
        }
        return gcd(save2, a % save2);
    }

    private boolean check(int[][] tempS, int roll_number) {
