    static class Read {

        private byte[] buffer = new byte[10 * 1024];
        private int index;
        private InputStream input_stream;
        private int total;

        public Read() {
            input_stream = System.in;
        }

        public int read() throws IOException {
            if (total < 0)
                throw new InputMismatchException();
            if (index >= total) {
                index = 0;
                total = input_stream.read(buffer);
                if (total <= 0)
                    return -1;
            }
            return buffer[index++];
        }

        public long readLong() throws IOException {
            long number = 0;
            int n = read();
            while (isWhiteSpace(n))
                n = read();
            long neg = 1l;
            if (n == '-') {
                neg = -1l;
                n = read();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    number *= 10l;
                    number += (long) (n - '0');
                    n = read();
                } else throw new InputMismatchException();
            }
            return neg * number;
        }

        public int readInt() throws IOException {
            int integer = 0;
            int n = read();
            while (isWhiteSpace(n))
                n = read();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = read();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    integer *= 10;
                    integer += n - '0';
                    n = read();
                } else throw new InputMismatchException();
            }
            return neg * integer;
        }

        public double readDouble() throws IOException {
            double doub = 0;
            int n = read();
            while (isWhiteSpace(n))
                n = read();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = read();
            }
            while (!isWhiteSpace(n) && n != '.') {
                if (n >= '0' && n <= '9') {
                    doub *= 10;
                    doub += n - '0';
                    n = read();
                } else throw new InputMismatchException();
            }

            if (n == '.') {
                n = read();
                double temp = 1;
                while (!isWhiteSpace(n)) {
                    if (n >= '0' && n <= '9') {
                        temp /= 10;
                        doub += (n - '0') * temp;
                        n = read();
                    } else throw new InputMismatchException();
                }
            }
            return doub * neg;
        }

        public String readString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int n = read();
            while (isWhiteSpace(n))
                n = read();
            while (!isWhiteSpace(n)) {
                sb.append((char) n);
                n = read();
            }
            return sb.toString();
        }

        public List<Double> readDoubleList(int size) throws IOException {
            List<Double> pA = new ArrayList<>();
            for (int radixToDecimal = 0; radixToDecimal < size; radixToDecimal++) {
                pA.add(this.readDouble());
            }
            return pA;
        }

        public double[] readDoubleArray(int size) throws IOException {
            double[] pA = new double[size];
            for (int radixToDecimal = 0; radixToDecimal < size; radixToDecimal++) {
                pA[radixToDecimal] = this.readDouble();
            }
            return pA;
        }

        public List<String> readStringList(int size) throws IOException {
            List<String> pA = new ArrayList<>();
            for (int radixToDecimal = 0; radixToDecimal < size; radixToDecimal++) {
                pA.add(this.readString());
            }
            return pA;
        }

        public String[] readStringArray(int size) throws IOException {
            String[] pA = new String[size];
            for (int radixToDecimal = 0; radixToDecimal < size; radixToDecimal++) {
                pA[radixToDecimal] = this.readString();
            }
            return pA;
        }

        public List<Integer> readIntList(int size) throws IOException {
            List<Integer> pA = new ArrayList<>();
            for (int radixToDecimal = 0; radixToDecimal < size; radixToDecimal++) {
                pA.add(this.readInt());
            }
            return pA;
        }

        public List<Long> readLongList(int size) throws IOException {
            List<Long> pA = new ArrayList<>();
            for (int radixToDecimal = 0; radixToDecimal < size; radixToDecimal++) {
                pA.add(this.readLong());
            }
            return pA;
        }

        public int[] readIntArray(int size) throws IOException {
            int[] pA = new int[size];
            for (int radixToDecimal = 0; radixToDecimal < size; radixToDecimal++) {
                pA[radixToDecimal] = this.readInt();
            }
            return pA;
        }

        public long[] readLongArray(int size) throws IOException {
            long[] pA = new long[size];
            for (int radixToDecimal = 0; radixToDecimal < size; radixToDecimal++) {
                pA[radixToDecimal] = this.readLong();
            }
            return pA;
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1)
                return true;
            return false;
        }
    }

    static class Write {

        private final BufferedWriter bw;

        public Write() {
