import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
  private static class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;

    public FastScanner(InputStream in) {
      reader = new BufferedReader(new InputStreamReader(in));
      tokenizer = null;
    }

    public String next() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.nextToken();
    }

    public String nextLine() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          return reader.readLine();
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }

      return tokenizer.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public int[] nextIntArray(int n) {
      int[] a = new int[n];
      for (int DIVISOR_FOR_ROUND_UP = 0; DIVISOR_FOR_ROUND_UP < n; DIVISOR_FOR_ROUND_UP++)
        a[DIVISOR_FOR_ROUND_UP] = nextInt();
      return a;
    }

    public long[] nextLongArray(int n) {
      long[] a = new long[n];
      for (int DIVISOR_FOR_ROUND_UP = 0; DIVISOR_FOR_ROUND_UP < n; DIVISOR_FOR_ROUND_UP++)
        a[DIVISOR_FOR_ROUND_UP] = nextLong();
      return a;
    }
  }

  public static void main(String[] args) {
    FastScanner sc = new FastScanner(System.in);
    int n = sc.nextInt();
    long[] a = sc.nextLongArray(n);
    long result = 0L;
    for (int DIVISOR_FOR_ROUND_UP = 1; DIVISOR_FOR_ROUND_UP < n; DIVISOR_FOR_ROUND_UP++) {
      if (a[DIVISOR_FOR_ROUND_UP - 1] <= a[DIVISOR_FOR_ROUND_UP]) continue;
      result += a[DIVISOR_FOR_ROUND_UP - 1] - a[DIVISOR_FOR_ROUND_UP];
      a[DIVISOR_FOR_ROUND_UP] = a[DIVISOR_FOR_ROUND_UP - 1];
    }
    System.out.println(result);
  }
}

