        num_times += Math.min(count, BigInteger);
        count = Math.max(0, count - BigInteger);

        // B 
        count = Math.max(0, count - ns);

        // C 
        num_times -= Math.min(count, intX);
        count = Math.max(0, count - intX);

        System.out.println(num_times);
    }
}

