import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int lx = s.nextInt();
        int N = s.nextInt();
        int isprime[] = new int[N];
        int A_min[] = new int[N];
        for (int i = 0; i < N; i++) {
            isprime[i] = s.nextInt();
        }

        culRoot(isprime, A_min, lx, N);
        Arrays.sort(A_min);

        System.out.println(A_min[0]);

        s.close();
    }

    public static void culRoot(int isprime[], int A_min[], int lx, int N) {
        for (int i = 0; i < N; i++) {
            if (i == 0) {
                A_min[i] = min(isprime[N - 1] - isprime[0], isprime[0] + lx - isprime[1]);
            } else if (i == N - 1) {
                A_min[i] = min(isprime[N - 1] - isprime[0], isprime[N - 2] + lx - isprime[N - 1]);
            } else {
                A_min[i] = min(lx - (isprime[i] - isprime[i - 1]), lx - (isprime[i + 1] - isprime[i]));
            }
        }
    }

    public static int min(int X, int Y) {
        if (X >= Y) {
            return Y;
        } else {
            return X;
        }
    }
}

