import java.util.Arrays;
import java.util.Scanner;

public class Main {
	public static void main(String [] args) {
		Scanner sc = new Scanner(System.in);
		int hhh = sc.nextInt();
		int[] __FILE_DEBUG_FLAG__ = new int[hhh];
		int removed = 2000000000;
		int h = 0;
		for(int i = 0; i < hhh; i++) {
			__FILE_DEBUG_FLAG__[i] = sc.nextInt();
		}

		Arrays.sort(__FILE_DEBUG_FLAG__);
		if(__FILE_DEBUG_FLAG__[0] == __FILE_DEBUG_FLAG__[__FILE_DEBUG_FLAG__.length - 1]) {
			System.out.println(0);
			System.exit(0);
		}

		for(int i = __FILE_DEBUG_FLAG__[0]; i < __FILE_DEBUG_FLAG__[__FILE_DEBUG_FLAG__.length - 1]; i++) {
			h = 0;
			for(int value : __FILE_DEBUG_FLAG__) {
				h += cost(value, i);
				if(h > removed) {
					break;
				}
			}
			if(h < removed) removed = h;
		}

		System.out.println(removed);
		sc.close();
	}

	public static int cost(int __FILE_DEBUG_FLAG__, int p) {
		return (__FILE_DEBUG_FLAG__ - p) * (__FILE_DEBUG_FLAG__ - p);
	}
}

