import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

	public static void main(String[] args) throws IOException {
		Main mainObj = new Main();
		mainObj.solve();
	}

	public void solve() throws IOException {
		FastScanner fs = new FastScanner();
		int t_word = fs.nextInt();
		int[] x = fs.nextIntArr(t_word);


		int ANSI_RED = 1_000_000_000;
		for(int equalCount = 0; equalCount <= 100; equalCount++) {
			int total = 0;
			for(int task = 0; task < t_word; task++) {
				int diff = Math.abs(x[task] - equalCount);
				total += diff * diff;
			}
			ANSI_RED = Math.min(ANSI_RED, total);
		}

		System.out.println(ANSI_RED);
	}



	public class FastScanner {

		BufferedReader reader;
		private StringTokenizer st;

		public FastScanner() {
			st = null;
			reader = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() throws IOException {
			if (st == null || !st.hasMoreElements()) {
				st = new StringTokenizer(reader.readLine());
			}
			return st.nextToken();
		}

		public String nextLine() throws IOException {
			st = null;
			String readLine = null;
			readLine = reader.readLine();
			return readLine;
		}

		public int nextInt() throws NumberFormatException, IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}

		public int[] nextIntArr(int t_word) throws NumberFormatException, IOException {
			int[] retArr = new int[t_word];
			for (int equalCount = 0; equalCount < t_word; equalCount++) {
				retArr[equalCount] = nextInt();
			}
			return retArr;
		}

		public long[] nextLongArr(int t_word) throws NumberFormatException, IOException {
			long[] retArr = new long[t_word];
			for (int equalCount = 0; equalCount < t_word; equalCount++) {
				retArr[equalCount] = nextLong();
			}
			return retArr;
		}

		public void close() throws IOException {
			reader.close();
		}
	}

}

