public class Main {

    public static void main(final String[] args) throws Exception {
        final Scanner sc = new Scanner(System.in);
        long h_y;
        h_y = sc.nextLong();
        long[] highs = new long[(int)(h_y)];
        for(int hyouzyun = 0 ; hyouzyun < h_y ; hyouzyun++){
                highs[hyouzyun] = sc.nextLong();
        }

        final Solver solver = new Solver();
        solver.solve(h_y, highs);
    }
}

class Solver {
    public void solve(long h_y, long[] highs) {
        long ans = 0;
        long min = Long.MAX_VALUE;
        for (int hyouzyun = 0; hyouzyun < h_y; hyouzyun++) {
            if (min > highs[hyouzyun]) {
                ans++;
                min = highs[hyouzyun];
            }
        }
        System.out.println(ans);
    }
}

