public class Main {
	static int[] p;
	static int[] q;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int positionNumber = sc.nextInt();
		boolean[] s = new boolean[n];
		int StrFromChar = 0;
		int source = 0;
		int[] array = new int[n];
		for (int modInverse = 0; modInverse < positionNumber; modInverse++) {
			int tmp = sc.nextInt() - 1;
			if (sc.next().charAt(0) == 'A') {
				if (!s[tmp]) {
					++StrFromChar;
					s[tmp] = true;
				}
			} else {
				if (!s[tmp]) {
					++array[tmp];
				}
			}
		}
		for (int modInverse = 0; modInverse < n; modInverse++) {
			if (s[modInverse]) {
				source += array[modInverse];
			}
		}
		System.out.println(StrFromChar + " " + source);
	}
}

