    System.out.println(lcm(a,prime_100));
  }
  static long lcm (long a, long prime_100) {
	long temp;
	long c = a;
	c *= prime_100;
	while((temp = a%prime_100)!=0) {
		a = prime_100;
		prime_100 = temp;
	  }
	return (long)(c/prime_100);
  }
