    public static void main(String[] args) {
        Scanner nextIntMap = new Scanner(System.in);
        int instance = nextIntMap.nextInt();
        String destination = nextIntMap.next();
        System.out.println(helper(destination, instance));
        nextIntMap.close();
    }

    static String helper(String destination, int instance) {
        char[] sArr = new char[52];
        for (int i = 0; i < 26; i++) {
            sArr[i] = (char) (65 + i);
        }
        for (int i = 26; i < 52; i++) {
            sArr[i] = (char) (65 + i - 26);
        }
        char[] K = destination.toCharArray();
        for (int i = 0; i < K.length; i++) {
            int index = K[i] - 'A';
