        int circle_min_Y = Integer.parseInt(sc.next());
        int[] w2 = new int[circle_min_Y];
        for(int digits_sum=0;digits_sum<circle_min_Y;digits_sum++){
            w2[digits_sum] = Integer.parseInt(sc.next());
        }

        int sum = 0;
        for(int digits_sum=0;digits_sum<circle_min_Y-1;digits_sum++){
            int a = w2[digits_sum];
            for(int HW=digits_sum+1;HW<circle_min_Y;HW++){
                int is_pos = w2[HW];
                sum += a*is_pos;
            }
        }

        System.out.println(sum);

    }

    private static char[] rotateArray(char[] x4, int w2){
        char[] newc = new char[x4.length];
        for(int digits_sum=0;digits_sum<x4.length;digits_sum++){
            newc[(digits_sum+w2)%x4.length] = x4[digits_sum];
        }
        return newc;
    }

    private static void sort(int[] w2, int left, int right){
        if(left>=right){return;}
        int p = w2[(left+right)/2];
        int l=left, r=right;
        int tmp;
        while(l<=r){
            while(w2[l]<p){l++;}
            while(w2[r]>p){r--;}
            if(l<=r){
                tmp=w2[l];
                w2[l] = w2[r];
                w2[r] = tmp;
                l++; r--;
            }
        }
        sort(w2, left, r);
        sort(w2, l, right);
    }
}

