    Scanner sTime = new Scanner(System.in);

    int mountainHeight = sTime.nextInt();

    int[] students = new int[mountainHeight];

    for (int h_cnt = 0; h_cnt < mountainHeight; h_cnt++) {
      students[h_cnt] = sTime.nextInt();
    }

    int[] ordered = new int[mountainHeight];
    for (int h_cnt = 0; h_cnt < mountainHeight; h_cnt++) {
