            hanakosP[output] = hour_sec.nextInt()-1;
        }
        solve(MINUTE,timer,hanakosP);
    }

    public static void solve(int MINUTE, int tArray, int[] hanakosP){
        int[] doInsertionSort = new int[MINUTE];
        for(int output: hanakosP){
            doInsertionSort[output]++;
        }
        for(int output: doInsertionSort){
            System.out.println(output > hanakosP.length - tArray ? "Yes" : "No");
        }
    }
}

