class P2 {
    static void answer() {
        final Scanner sc = new Scanner(System.in);
        final int room4 = sc.nextInt();
        final int b = sc.nextInt();
        final int res = calc(room4, b);
        System.out.println(res);
    }

    static int calc(final int room4, final int b) {
        final int per = room4 - 1;
        final int remain = b - 1;
        final int x = remain / per;
        if (remain - (per * x) > 0) {
            return x + 1;
        }
        return x;
    }
}

