		Scanner sc = new Scanner(System.in);
		String suitChar = sc.next();
		int dd = suitChar.length();
		int h3 = Integer.parseInt(suitChar);
		int ans = 0;
		switch(dd%2){
			case 0:
			for(int i = 0; i < dd; i+=2)ans += 9 * Math.pow(10, i);
			break;

			case 1:
			if(dd == 1){
				ans = h3;
				break;
			}
			for(int i = 0; i < dd-1; i+=2)ans += 9 * Math.pow(10, i);
			ans += Integer.parseInt(suitChar.substring(1))+1;
			ans += (Integer.parseInt(suitChar.substring(0, 1)) - 1) * Math.pow(10, dd-1);
			break;
		}

		System.out.println(ans);
	}
}

