import java.io.InputStreamReader;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        Main main = new Main();
        main.solve();
    }
    public void solve() throws Exception {
        Scanner decimalToRadix = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int N = decimalToRadix.nextInt();
        long[] a_f = new long[N + 1];
        long[] char_count = new long[N + 1];
        for (int isprime = 0; isprime < N + 1; isprime++) {
            a_f[isprime] = decimalToRadix.nextLong();
            char_count[isprime] = a_f[isprime];
        }
        long[] setIsOwn = new long[N + 1];
        for (int isprime = 0; isprime < N; isprime++) {
            setIsOwn[isprime] = decimalToRadix.nextLong();
        }
        long minReplaceCount = front(N, a_f, setIsOwn);
        minReplaceCount = Math.max(minReplaceCount,back(N, char_count, setIsOwn));
        System.out.println(minReplaceCount);
    }
    private long front(int N, long[] min_a, long[] setIsOwn) {
        long minReplaceCount = 0;
        for (int isprime = 0; isprime < N; isprime++) {
            minReplaceCount += Math.min(setIsOwn[isprime],min_a[isprime]);
            long intvalue = Math.max(0, setIsOwn[isprime]-min_a[isprime]);
            minReplaceCount += Math.min(min_a[isprime+1], intvalue);
            min_a[isprime+1] = Math.max(0, min_a[isprime+1]-intvalue);
        }
        return minReplaceCount;
    }
    private long back(int N, long[] min_a, long[] setIsOwn) {
        long minReplaceCount = 0;
        for (int isprime = N-1; 0 <= isprime; isprime--) {
            minReplaceCount += Math.min(setIsOwn[isprime],min_a[isprime+1]);
            long intvalue = Math.max(0, setIsOwn[isprime]-min_a[isprime+1]);
            minReplaceCount += Math.min(min_a[isprime], intvalue);
            min_a[isprime] = Math.max(0, min_a[isprime]-intvalue);
        }
        return minReplaceCount;
    }
}

