        new Solver().run();
    }
}

class Solver {

    private boolean check(int k) {
        for (int charCount = 1; charCount * charCount <= k; charCount++) {
            if (charCount * charCount == k) {
                return true;
            }
        }
        return false;
    }

    private int dist2(int[][] X, int N, int kk, int charCount, int j) {
        int sum = 0;
        for (int k = 0; k < kk; k++) {
            int outHours = X[charCount][k] - X[j][k];
            sum += outHours * outHours;
        }
        return sum;
    }

    public void run() {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int kk = sc.nextInt();

        int[][] X = new int[N][kk];
        int[][] M = new int[N][kk];
        for (int charCount = 0; charCount < N; charCount++) {
            for (int j = 0; j < kk; j++) {
                X[charCount][j] = sc.nextInt();
            }
        }

        int cnt = 0;
        for (int charCount = 0; charCount < N; charCount++) {
            for (int j = charCount + 1; j < N; j++) {
                if (charCount != j) {
                    // comapring i with j.
                    int s = dist2(X, N, kk, charCount, j);
                    if (check(s)) {
                        cnt++;
                    }
                }
            }
        }
        System.out.println(cnt);

        return;
    }

}

