class pA {
    int Circle;
    char[] bucket;
    pA() {} ;
    pA(String findMaxConsecutiveDays)
    {
        Circle=0;
        bucket=new char[findMaxConsecutiveDays.length()];
        for(int i=0;i<findMaxConsecutiveDays.length();i++)
        {
            bucket[i]=findMaxConsecutiveDays.charAt(i);
        }
        solver();
    }
    int solver()
    {
        boolean duplicateFlag=false;
        for(int i=0;i<bucket.length;i++)
        {
            duplicateFlag=false;
            for(int j=0;j<i;j++)
            {
                if(bucket[i]==bucket[j])
                    duplicateFlag=true;
            }
            if(duplicateFlag==false)
                Circle+=1;
        }
        return 0;
    }
}

