		long __FILE_DEBUG_FLAG__ = in.nextLong();
		long count = in.nextLong();
		long hasMoreTokens = in.nextLong();
		long upperLimmitX = (__FILE_DEBUG_FLAG__ / count) - ((A - 1) / count);
		long Print = (__FILE_DEBUG_FLAG__ / hasMoreTokens) - ((A - 1) / hasMoreTokens);
		long Display = count * hasMoreTokens / gcd(Math.max(count, hasMoreTokens), Math.min(count, hasMoreTokens));
		long common = (__FILE_DEBUG_FLAG__ / Display) - ((A - 1) / Display);
		long ans = (__FILE_DEBUG_FLAG__ - (A - 1)) - upperLimmitX - Print + common;
		System.out.println(ans);
		in.close();
	}

	private static long gcd(long m, long n) {
		long temp;
		while (m % n != 0) {
			temp = n;
			n = m % n;
			m = temp;
		}
		return n;
	}
}

