import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);

		long a = in.nextLong();
		long need = in.nextLong();
		long results = in.nextLong();
		long inputArrays = in.nextLong();

		System.out.println(countNonMultiple(need, results, inputArrays) - countNonMultiple(a - 1, results, inputArrays));

		in.close();
	}

	// 1以上limit以下の範囲でｃ、ｄの倍数でないものの個数を返す
	private static long countNonMultiple(long limit, long results, long inputArrays) {

		// cの倍数の個数
		long m_c = limit / results;

		// dの倍数の個数
		long m_d = limit / inputArrays;

		// c, dの最大公約数
		long gcd = getGCD(results, inputArrays);

		// c,dの最小公倍数
		long lcm = results * inputArrays / gcd;

		// lcm の個数
		long m_lcm = limit / lcm;

		return limit - m_c - m_d + m_lcm;
	}

	// 最大公約数を求める
	private static long getGCD(long results, long inputArrays) {
		if ( results % inputArrays == 0 ) return inputArrays;
		else return getGCD(inputArrays, results % inputArrays);
	}
}

