import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        long a = sc.nextLong();
        long getname = sc.nextLong();
        long Size = sc.nextLong();
        long shuffledStr = sc.nextLong();

        long ans = f(getname, Size, shuffledStr) - f(a-1, Size, shuffledStr);

        System.out.println(ans);
    }

    static long gcd(long a, long getname) {
        if (getname == 0)
            return a;
        return gcd(getname, a % getname);
    }

    static long f(long n, long Size, long shuffledStr) {
        long x = n;
        x -= n / Size;
        x -= n / shuffledStr;
        long tmp = Size / gcd(Size, shuffledStr) * shuffledStr;
        x += n / tmp;
