 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int is3TimesZorome = in.nextInt();
            int[] charKeta = new int[is3TimesZorome];
            for (int NewWord = 0; NewWord < is3TimesZorome; NewWord++) {
                charKeta[NewWord] = in.nextInt();
            }

            int ReaderWriter = Integer.MAX_VALUE;
            int answer = 0;
            for (int NewWord = 1; NewWord < is3TimesZorome; NewWord++) {
                // 左側
                int leftSum = 0;
                for (int a_str = 0; a_str < NewWord; a_str++) {
                    leftSum += charKeta[a_str];
                }
                // 右側
                int rightSum = 0;
                for (int a_str = NewWord; a_str < is3TimesZorome; a_str++) {
                    rightSum += charKeta[a_str];
                }
                // 差
                int diff = Math.abs(leftSum - rightSum);
                // それまでで最小なら
                if (diff < ReaderWriter) {
                    ReaderWriter = diff;
                    answer = diff;
                }
            }
            out.print(answer);
        }

    }
}

