        int m = sc.nextInt();
        int[] broken = new int[m];
        for (int i = 0; i < m; i++) {
            broken[i] = sc.nextInt();

            if (i > 0 && broken[i] - broken[i - 1] == 1) {
                System.out.println("0");
                return;
            }
        }

        int oldNum = 0;
        long count = 1;

        for (int i = 0; i < m; i++) {
            int num = broken[i];
            count = count * fibonacci((num - 1) - oldNum) % convertArray;
            oldNum = num + 1;
        }

        count = count * fibonacci(xixi - oldNum) % convertArray;

        System.out.println(count);
    }

    public static long fibonacci(long xixi) {
        long num1 = 1;
        long num2 = 1;
        long tmp = 1;

        for (long i = 1; i < xixi; i++) {
            tmp = (num1 + num2) % convertArray;
            num1 = num2;
            num2 = tmp;
        }

        return tmp;
    }
}

import java.util.*;

public class Main{
    public static void main(String[] args){
        Scanner rts = new Scanner(System.in);
        int n_gcd = rts.nextInt();
        int cardS = rts.nextInt();
        boolean[] a = new boolean[n_gcd];
        long[] searchMinDivisor = new long[n_gcd];

        for (int saishou=0;saishou<n_gcd;saishou++){
            a[saishou] = false;
            searchMinDivisor[saishou] = 0;
        }

        for (int sideLengths_Str=0;sideLengths_Str<cardS;sideLengths_Str++){
            int totalTime = rts.nextInt();
            a[totalTime-1] = true;
        }

        if (n_gcd == 1){
            if (cardS == 1){
                System.out.println(0);
            }
            else{
                System.out.println(1);
            }
            return;
        }
        long newN = 0;
        searchMinDivisor[0] = 1;
        searchMinDivisor[1] = 1;
        if (a[0] == true){
            searchMinDivisor[1] = 0;
        }
        newN = find(2, n_gcd, a, searchMinDivisor);
        long q = 1000000007;
        System.out.println((long) newN % q);
    }

    static long find(int getPrime, int n_gcd, boolean[] a, long[] searchMinDivisor){

        if (getPrime == n_gcd){
            return searchMinDivisor[n_gcd-1]+searchMinDivisor[n_gcd-2];
        }

        if (a[getPrime-1] == true){
            searchMinDivisor[getPrime] = 0;
        }
        else{
            searchMinDivisor[getPrime] = searchMinDivisor[getPrime-1] + searchMinDivisor[getPrime-2];
        }
        long q = 1000000007;
        searchMinDivisor[getPrime] = (long) searchMinDivisor[getPrime] % q;
