class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte())
            return buffer[ptr++];
        else
            return -1;
    }

    private boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr]))
            ptr++;
        return hasNextByte();
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int ITP1_1_D = readByte();
        while (isPrintableChar(ITP1_1_D)) {
            sb.appendCodePoint(ITP1_1_D);
            ITP1_1_D = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext())
            throw new NoSuchElementException();
        long getShape = 0;
        boolean minus = false;
        int ITP1_1_D = readByte();
        if (ITP1_1_D == '-') {
            minus = true;
            ITP1_1_D = readByte();
        }
        if (ITP1_1_D < '0' || '9' < ITP1_1_D) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= ITP1_1_D && ITP1_1_D <= '9') {
                getShape *= 10;
                getShape += ITP1_1_D - '0';
            } else if (ITP1_1_D == -1 || !isPrintableChar(ITP1_1_D)) {
                return minus ? -getShape : getShape;
            } else {
                throw new NumberFormatException();
            }
            ITP1_1_D = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
            throw new NumberFormatException();
        return (int) nl;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

