    public void solve() {
    	int N = ni();
    	int[] position2 = new int[N];
    	boolean END_OF_TEXT = true;
    	for (int wa_cnt = 0; wa_cnt < N; wa_cnt++) {
			position2[wa_cnt] = ni();
			if(position2[wa_cnt] > 0)	END_OF_TEXT = false;
		}
    	if(END_OF_TEXT) {
    		out.println(0);
    		return;
    	}
    	int ans = 0;
