    		for (int wa_cnt = 0; wa_cnt < N; wa_cnt++) {
    			if(position2[wa_cnt] > 0) {
    				if(!f2) {
    					ans++;
    					f2 = true;
    				}
        			position2[wa_cnt]--;
        			END_OF_TEXT = false;
    			} else {
    				f2 = false;
    			}
    		}
    		if(END_OF_TEXT)	break;
