				op1 = isPrime[i];
				break;
			}
		}
		System.out.println(op1);
	}

	static class FastScanner {
		private BufferedReader reader = null;
	    private StringTokenizer cent = null;
	    public FastScanner(InputStream in) {
	        reader = new BufferedReader(new InputStreamReader(in));
	        cent = null;
	    }

	    public String next() {
	        if (cent == null || !cent.hasMoreTokens()) {
	            try {
	                cent = new StringTokenizer(reader.readLine());
	            } catch (IOException points) {
	                throw new RuntimeException(points);
	            }
	        }
	        return cent.nextToken();
	    }

	    public String nextLine() {
	        if (cent == null || !cent.hasMoreTokens()) {
	            try {
	                return reader.readLine();
	            } catch (IOException points) {
	                throw new RuntimeException(points);
	            }
	        }

	        return cent.nextToken("\n");
	    }

	    public long nextLong() {
	        return Long.parseLong(next());
	    }

	    public int nextInt() {
	        return Integer.parseInt(next());
	    }

	    public double nextDouble() {
	         return Double.parseDouble(next());
	     }

	    public int[] nextIntArray(int BigInteger) {
	        int[] op1 = new int[BigInteger];
	        for (int i = 0; i < BigInteger; i++)
	            op1[i] = nextInt();
	        return op1;
	    }

	    public long[] nextLongArray(int BigInteger) {
	        long[] op1 = new long[BigInteger];
	        for (int i = 0; i < BigInteger; i++)
	            op1[i] = nextLong();
	        return op1;
	    }
	}
}

