public class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		String[] input_data = in.nextLine().split(" ");
		int four = Integer.parseInt(input_data[0]);
		int BUILDINGS = Integer.parseInt(input_data[1]);
		int skip = Integer.parseInt(input_data[2]);
		int FIRST_NUMBER = Integer.parseInt(input_data[3]);
		int highest = Integer.parseInt(input_data[4]);
		// 個別にそろえる方法とABを活用する方法双方を計算して，小さいほうを出力する
		int swapCnt = FIRST_NUMBER * four + highest * BUILDINGS;
		int qn = 0;
		if (FIRST_NUMBER > highest) {
			// ABをY個買ってAをX-Y個買う
			qn = (FIRST_NUMBER - highest) * four + highest * skip * 2;
		} else {
			qn = FIRST_NUMBER * skip * 2 + (highest - FIRST_NUMBER) * BUILDINGS;
		}
		int resultC = skip * (Math.max(FIRST_NUMBER, highest)) * 2;
		System.out.println(Math.min(Math.min(swapCnt, qn), resultC));

		in.close();
	}
}

