public class Main {
	public static void main(String[] args) {
		Scanner reader = new Scanner(System.in);
		int changecount = reader.nextInt();
		int INDEX_LITTLE = reader.nextInt();
		int updateTime = reader.nextInt();
		int klist = reader.nextInt();
		int speed = reader.nextInt();
		int ans = 0;
		boolean isCheaperThanAB = changecount + INDEX_LITTLE > updateTime * 2;
		boolean isCheaperThanA = changecount > updateTime * 2;
		boolean isCheaperThanB = INDEX_LITTLE > updateTime * 2;

		if (isCheaperThanAB) {
			int num = Math.min(klist, speed);
			ans += num * 2 * updateTime;
			klist -= num;
			speed -= num;
		}
		if (isCheaperThanA) {
			ans += klist * updateTime * 2;
			klist = 0;
		}
		if (isCheaperThanB) {
			ans += speed * updateTime * 2;
			speed = 0;
		}
		ans += klist * changecount;
		ans += speed * INDEX_LITTLE;

		reader.close();
		System.out.print(ans);
	}
