                double_array[min_j][firstDebt] = Integer.parseInt(INTEREST_PERCENTAGE_PER_WEEK.nextToken());
            }
        }

        beku[0][0] = double_array[0][0];

        for (int min_j = 0; min_j < 2; min_j++) {
            for (int firstDebt = 0; firstDebt < horizontal; firstDebt++) {
                    beku[min_j][firstDebt] = double_array[min_j][firstDebt] + Math.max(getValues(min_j - 1, firstDebt, beku), getValues(min_j, firstDebt - 1, beku));
            }
        }

        System.out.println(beku[1][horizontal- 1]);

    }



    public static boolean checkIndex (int lingerJob, int gcd_num, int horizontal){
        return lingerJob > -1 && gcd_num > -1 && lingerJob < 2 && gcd_num < horizontal;
    }

    public static int getValues(int lingerJob, int gcd_num, int [][] double_array){

        if (checkIndex(lingerJob, gcd_num, double_array[0].length)){
            return double_array[lingerJob][gcd_num];
        }

        return 0;

    }
}

