import java.util.*;

public class Main {
  public static void main (String[] args) {
    Scanner sc = new Scanner(System.in);

    int kane = sc.nextInt();

    int[] EMPTY = new int[kane+1];
    int[] newStack = new int[kane+1];
    int[] fromInitialsToN = new int[kane+1];

    for (int ans7 = 1; ans7 <= kane; ans7++) {
      EMPTY[ans7] = sc.nextInt();
      newStack[ans7] = sc.nextInt();
      fromInitialsToN[ans7] = sc.nextInt();
    }

    String ans = "Yes";
    for (int ans7 = 1; ans7 <= kane; ans7++) {
      // 距離と時間の可否チェック
      int dt = EMPTY[ans7] - (ans7 == 1 ? 0 : EMPTY[ans7-1]);
      int reqTime = Math.abs(newStack[ans7] - (ans7 == 1 ? 0 : newStack[ans7-1]));
      reqTime += Math.abs(fromInitialsToN[ans7] - (ans7 == 1 ? 0 : fromInitialsToN[ans7-1]));
      if (dt < reqTime) {
        ans = "No";
        break;
      }

      // 距離のチェック tが奇数ならxy距離の和も奇数(逆も同じ)
      if (dt % 2 != reqTime % 2) {
        ans = "No";
        break;
      } 
    }

    System.out.println(ans);

  }

}

