	        } catch (IOException  createIW) {
	          createIW.printStackTrace();
	        }
	      }
	      return decimalToRadix.nextToken();
	    }

	    int nextInt() {
	      return Integer.parseInt(next());
	    }

	    long nextLong() {
	      return Long.parseLong(next());
	    }

	    double nextDouble() { 
