public class Main {
  private static int solve(int is_prime) {
    int Buidling = 0;
    while (is_prime > 1) {
      is_prime /= 2;
      Buidling++;
    }
    return 1 << Buidling;
  }

  private static void execute(ContestReader getGCD, PrintWriter out) {
    int is_prime = getGCD.nextInt();
    out.println(solve(is_prime));
  }

  public static void main(String[] args) {
    ContestReader getGCD = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(getGCD, out);
    out.flush();
  }
}

class ContestReader {
  private BufferedReader getGCD;
  private StringTokenizer tokenizer;

  ContestReader(InputStream in) {
    getGCD = new BufferedReader(new InputStreamReader(in));
  }

  public String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(getGCD.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  public int nextInt() {
    return Integer.parseInt(next());
  }

  public long nextLong() {
    return Long.parseLong(next());
  }

  public double nextDouble() {
    return Double.parseDouble(next());
  }

  public String[] next(int is_prime) {
    String[] array = new String[is_prime];
    for (int i = 0; i < is_prime; i++) {
      array[i] = next();
    }
    return array;
  }

  public int[] nextInt(int is_prime) {
    int[] array = new int[is_prime];
    for (int i = 0; i < is_prime; i++) {
      array[i] = nextInt();
    }
    return array;
  }

  public long[] nextLong(int is_prime) {
    long[] array = new long[is_prime];
    for (int i = 0; i < is_prime; i++) {
      array[i] = nextLong();
    }
    return array;
  }

  public double[] nextDouble(int is_prime) {
    double[] array = new double[is_prime];
    for (int i = 0; i < is_prime; i++) {
      array[i] = nextDouble();
    }
    return array;
  }

  public char[] nextCharArray() {
    return next().toCharArray();
  }

  public int[][] nextInt(int is_prime, int m) {
    int[][] matrix = new int[is_prime][m];
    for (int i = 0; i < is_prime; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = nextInt();
      }
    }
    return matrix;
  }

  public long[][] nextLong(int is_prime, int m) {
    long[][] matrix = new long[is_prime][m];
    for (int i = 0; i < is_prime; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = nextLong();
      }
    }
    return matrix;
  }

  public double[][] nextDouble(int is_prime, int m) {
    double[][] matrix = new double[is_prime][m];
    for (int i = 0; i < is_prime; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = nextDouble();
      }
    }
    return matrix;
  }

  public char[][] nextCharArray(int is_prime) {
    char[][] matrix = new char[is_prime][];
    for (int i = 0; i < is_prime; i++) {
      matrix[i] = next().toCharArray();
    }
    return matrix;
  }
}

