public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int curChar = scanner.nextInt();

        int dividedCount = 0;
        int printIntMatrix = 0;
        int tmp = 0;
        int output = 0;
        int target = 0;

        for(int i=curChar; i>0; i--) {
            if(curChar == 1) {
                output = 1;
                break;
            }
            if(i % 2 == 0) {
                target = i;
                tmp = i;
                while(true) {
                    if(target % 2 != 0) {
                        break;
                    } else {
                        dividedCount += 1;
                        target /= 2;
                    }
                }
                if(printIntMatrix < dividedCount) {
                    printIntMatrix = dividedCount;
                    output = tmp;
                }
                dividedCount = 0;
            }
        }
        System.out.println(output);
    }
}

