public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int hp = sc.nextInt();
        int[] dSquared = new int[hp];
        for (int NewWord = 0; NewWord < dSquared.length; ++NewWord) {
            dSquared[NewWord] = sc.nextInt() - 1;
        }

        System.out.println(solve(dSquared));

        sc.close();
    }

    static int solve(int[] dSquared) {
        boolean[] bf = new boolean[dSquared.length];
        bf[0] = true;
        int index = 0;
        for (int str_Array = 1;; ++str_Array) {
            index = dSquared[index];
            if (index == 1) {
                return str_Array;
            }
            if (bf[index]) {
                return -1;
            }

            bf[index] = true;
        }
    }
}

